// `musette-native` is generated by `npm run generate:android|ios` in
// modules/musette-native (crates/musette-ffi, uniffi-bindgen-react-native).
import * as ffi from 'musette-native';
import type { Cc600Field, Core, RouteAnalysis } from './types';

/** Copy of the bytes as an ArrayBuffer of their own, as UniFFI takes them. */
const buf = (b: Uint8Array): ArrayBuffer => b.slice().buffer as ArrayBuffer;
const bytes = (b: ArrayBuffer): Uint8Array => new Uint8Array(b);

/** UniFFI errors carry the musette-core message: rethrow it as a plain Error. */
function plain<T>(f: () => T): T {
  try {
    return f();
  } catch (e) {
    if (ffi.FfiError.Core.instanceOf(e)) throw new Error(e.inner.message);
    throw e;
  }
}

/** iOS and Android: the Rust core linked into the app (UniFFI). */
export async function loadPlatformCore(): Promise<Core> {
  await ffi.uniffiInitAsync();
  return {
    analyzeRoute: (lats, lons, eles) => plain(() => ffi.analyzeRoute(lats, lons, eles) as RouteAnalysis),
    parseGpx: (text) => plain(() => ffi.parseGpx(text)),
    verifyFit: (b) => plain(() => ffi.verifyFit(buf(b))),
    brytonFindActivities: (paths, sizes) =>
      ffi.brytonFindActivities(paths, sizes).map((a) => ({
        id: a.id,
        size: a.size === undefined ? undefined : Number(a.size),
      })),
    cc600Encode: (op, seq, payload) => plain(() => bytes(ffi.cc600Encode(op, seq, buf(payload)))),
    cc600Decode: (b) =>
      plain(() => {
        const f = ffi.cc600Decode(buf(b));
        return f && { op: f.op, seq: f.seq, payload: bytes(f.payload), consumed: f.consumed };
      }),
    cc600BuildRoute: (name, lats, lons, eles) => plain(() => bytes(ffi.cc600BuildRoute(name, lats, lons, eles))),
    cc600TransferBegin: (kind, b) => plain(() => bytes(ffi.cc600TransferBegin(kind, buf(b)))),
    cc600TransferChunk: (offset, data) => bytes(ffi.cc600TransferChunk(offset, buf(data))),
    cc600Sender(size) {
      const s = new ffi.Cc600Sender(size);
      return {
        ready: (p) => plain(() => s.ready(buf(p))),
        ack: (p) => plain(() => s.ack(buf(p))),
        resend: (p) => plain(() => s.resend(buf(p))),
        nextChunk: (max) => {
          const c = s.nextChunk(max);
          return c ? [c[0], c[1]] : undefined;
        },
        done: () => s.done(),
        permille: () => s.permille(),
        free: () => s.uniffiDestroy(),
      };
    },
    cc600Receiver(window, free) {
      const r = new ffi.Cc600Receiver(window, free);
      return {
        handle: (op, payload) =>
          plain(() => {
            const answer = r.handle(op, buf(payload));
            return answer && bytes(answer);
          }),
        disconnect: () => r.disconnect(),
        received: () => r.received(),
        committed: () => {
          const c = r.committed();
          return c && bytes(c);
        },
      };
    },
    cc600SettingsFields: () => ffi.cc600SettingsFields() as Cc600Field[],
    cc600SettingsParse: (text) => Object.fromEntries(ffi.cc600SettingsParse(text).map((s) => [s.key, s.value])),
    cc600SettingsApply: (current, changes) => plain(() => ffi.cc600SettingsApply(current, changes)),
  };
}
